const fs = require('fs').promises;
const path = require('path');

const EXPORT_VERSION = '1.0.0';
const DEFAULT_OUTPUT_DIR = 'synclistic-exports';
const MEDIA_SUBDIR = 'media';
const VALID_EXPORT_OBJECT_TYPES = Object.freeze([
  'articles',
  'blogs',
  'collections',
  'media',
  'menus',
  'pages',
  'products'
]);

function generateTimestamp(now = new Date()) {
  return now.toISOString().replace(/[:.]/g, '-').slice(0, 19);
}

function generateFilename(storeName, objectType, timestamp) {
  const safeName = String(storeName || 'store').replace(/[^a-zA-Z0-9-_]/g, '_');
  return `${safeName}_${objectType}_${timestamp}.json`;
}

async function ensureDirectory(dirPath, deps = {}) {
  const fsPromises = deps.fs || fs;

  try {
    await fsPromises.mkdir(dirPath, { recursive: true });
  } catch (error) {
    if (error.code !== 'EEXIST') {
      throw error;
    }
  }
}

async function readExportFile(filepath, deps = {}) {
  const fsPromises = deps.fs || fs;

  try {
    const content = await fsPromises.readFile(filepath, 'utf8');
    const data = JSON.parse(content);

    if (!data.version || !data.objectType || !Array.isArray(data.data)) {
      throw new Error('Invalid export file format: missing required fields');
    }

    return data;
  } catch (error) {
    if (error.code === 'ENOENT') {
      throw new Error(`Export file not found: ${filepath}`);
    }

    throw error;
  }
}

async function listExportFiles(dirPath, deps = {}) {
  const fsPromises = deps.fs || fs;
  const logger = deps.logger;
  const exportFiles = [];

  try {
    const files = await fsPromises.readdir(dirPath);
    const jsonFiles = files.filter((file) => file.endsWith('.json'));

    for (const file of jsonFiles) {
      const filepath = path.join(dirPath, file);

      try {
        const data = await readExportFile(filepath, deps);
        exportFiles.push({
          filename: file,
          filepath,
          objectType: data.objectType,
          storeName: data.storeName,
          store: data.store,
          count: data.count,
          createdAt: data.createdAt
        });
      } catch (error) {
        if (logger && typeof logger.verbose === 'function') {
          logger.verbose('Export', `Skipping invalid file: ${file}`);
        }
      }
    }

    return exportFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      return [];
    }

    throw error;
  }
}

module.exports = {
  EXPORT_VERSION,
  DEFAULT_OUTPUT_DIR,
  MEDIA_SUBDIR,
  VALID_EXPORT_OBJECT_TYPES,
  ensureDirectory,
  generateFilename,
  generateTimestamp,
  listExportFiles,
  readExportFile
};
